/* Private event workshop. All writes require a fresh server-side administrator check. */
(() => {
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),copy=x=>JSON.parse(JSON.stringify(x));
 const themes={convergence:'Convergence · azur et or',eclipse:'Éclipse · lune écarlate',nocturne:'Nocturne · brume violette'},metrics={boosters:'Boosters ouverts',cards:'Copies obtenues',characters:'Personnages distincts obtenus',duplicates:'Doublons obtenus',universe:'Cartes d’un anime',universes:'Animes distincts',mythics:'Copies mythiques obtenues',awakenings:'Cartes ayant débloqué un Éveil',resonance:'Résonances obtenues',resonant_cards:'Cartes ayant gagné une Résonance'},kinds={badge:'Insigne',title:'Titre',frame:'Cadre de profil',decoration:'Décoration',background:'Fond de profil',effect:'Effet de carte'};
 let owner='',epoch=0,busy=false,drafts=[],editing=null,dirty=false,rules=null,message='',page=0,queued=false;
 const $=id=>document.getElementById(id),root=()=>$('ks-anomalies'),account=()=>window.KizunaAccount?.getSnapshot?.()||{},allowed=()=>!!account().user?.id&&!account().loading&&account().isAdmin===true;
 const options=(items,value)=>Object.entries(items).map(([v,label])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
 const stamp=v=>v?new Date(v).toISOString().slice(0,16):'';
 const challenge=(i=1)=>({id:'defi-'+i,label:'Ouvrir des boosters',description:'Chaque booster ouvert pendant la période compte.',difficulty:'discovery',metric:'boosters',goal:3,universe:'',card_ids:[],min_level:1,reward:{kind:'badge',label:'Premier lien',style:'convergence'}});
 const fresh=()=>({title:'',description:'',theme:'convergence',image:'',image_source:'',starts_at:null,ends_at:null,challenges:[challenge()]});
 function status(text){message=text;if($('kanAdminStatus'))$('kanAdminStatus').textContent=text;}
 function controls(){root()?.querySelectorAll('#kanEventForm input,#kanEventForm select,#kanEventForm textarea').forEach(n=>n.disabled=busy);root()?.querySelectorAll('[data-kan-write]').forEach(n=>n.disabled=busy);for(const id of ['kanPublish','kanToggle','kanArchive','kanParticipants']){const n=$(id);if(n)n.disabled=busy||!editing?.id||((id==='kanPublish')&&dirty)||((id==='kanToggle'||id==='kanArchive')&&(!editing?.live||editing?.live?.status==='archived'))||((id==='kanArchive')&&Date.parse(editing?.live?.config.ends_at)>Date.now());}}
 function mount(){const key=allowed()?account().user.id:'';if(key!==owner){epoch++;owner=key;busy=false;drafts=[];editing=null;rules=null;dirty=false;$('kanStaffTab')?.remove();root()?.remove();}
  if(!allowed()||!$('staffPage')||root())return;
  const tab=document.createElement('button');tab.id='kanStaffTab';tab.type='button';tab.dataset.ksTab='anomalies';tab.textContent='Anomalies & Éveils';tab.setAttribute('aria-controls','ks-anomalies');tab.setAttribute('aria-pressed','false');$('staffPage').querySelector('.ks-tabs').append(tab);
  const panel=document.createElement('section');panel.id='ks-anomalies';panel.className='ks-panel kan-admin';panel.hidden=true;panel.innerHTML='<header><span class="kan-eyebrow">LE PROCHAIN CHAPITRE</span><h2>Les Anomalies de Kizuna</h2><p>Compose une ambiance, programme les dates puis publie les défis. Les brouillons restent privés.</p></header><p id="kanAdminStatus" role="status" aria-live="polite"></p><div class="ka-actions"><button type="button" class="ks-button" data-kan-admin="new" data-kan-write>Nouvelle Anomalie</button><button type="button" class="ks-button ks-secondary" data-kan-admin="refresh" data-kan-write>Actualiser</button></div><div id="kanAdminList" class="kan-admin-list"></div><form id="kanEventForm" class="kan-admin-form"></form><div id="kanAdminPreview" class="kan-preview-box" hidden></div><section id="kanParticipantsPanel" hidden></section><section class="kan-thresholds"><h3>Paliers des Éveils mythiques</h3><p>Un doublon mythique issu d’un booster donne une Résonance. Les Éveils déjà débloqués restent acquis après un changement de seuil.</p><form id="kanThresholdForm"></form></section>';
  $('staffPage').querySelector('.ks-wrap').append(panel);tab.addEventListener('click',()=>{window.KizunaStaff?.activate?.('anomalies');load();});panel.addEventListener('click',click);panel.addEventListener('submit',submit);panel.addEventListener('input',e=>{if(e.target.closest('#kanEventForm')){dirty=true;$('kanAdminPreview').hidden=true;controls();}});panel.addEventListener('change',e=>{if(e.target.closest('#kanEventForm')){dirty=true;controls();}});form();
 }
 function list(){if(!$('kanAdminList'))return;$('kanAdminList').innerHTML=drafts.map(d=>`<button type="button" data-kan-edit="${esc(d.id)}" data-kan-write><strong>${esc(d.config.title)}</strong><small>${d.live?(d.live.status==='archived'?'Archivée':!d.live.enabled?'Désactivée':Date.parse(d.live.config.starts_at)>Date.now()?'Programmée':Date.parse(d.live.config.ends_at)<=Date.now()?'Terminée':'En cours'):'Brouillon privé'} · ${d.participants} participant(s)${d.revision>d.published_revision&&d.live?' · modifications non publiées':''}</small></button>`).join('')||'<p>Aucun événement enregistré.</p>';controls();}
 function renderThresholds(){if(!$('kanThresholdForm'))return;$('kanThresholdForm').innerHTML=rules?'<div class="kan-admin-grid">'+rules.thresholds.map((n,i)=>`<label>Éveil ${i+1}<input type="number" name="level${i}" value="${n}" min="1" max="100000" step="1" required data-kan-write></label>`).join('')+'</div><button type="submit" class="ks-button ks-secondary" data-kan-write>Enregistrer les seuils</button>':'<p>Charge les paramètres pour modifier les seuils.</p>';controls();}
 async function run(action,payload={}){if(busy||!allowed())return;busy=true;const token=epoch,key=owner;controls();status('Enregistrement…');try{const r=await window.KizunaAccount.anomalyRequest(action,payload);if(token!==epoch||key!==owner||!allowed())return;return r;}catch(e){if(token===epoch)status(e.publicMessage||e.message);return null;}finally{if(token===epoch){busy=false;controls();}}}
 async function load(){if(busy||!allowed())return;const token=epoch,r=await run('admin_list');if(!r||token!==epoch)return;drafts=r.drafts;list();status(drafts.length+' Anomalie(s) enregistrée(s).');try{const m=await window.KizunaAccount.mythicRequest('get');if(token!==epoch||!allowed())return;rules=m.rules;renderThresholds();}catch(e){if(token===epoch)status(e.message);}}
 function challengeForm(c,i){const cards=window.KizunaGame?.getSnapshot?.().cards||[],universes=Object.fromEntries([...new Set(cards.map(x=>x.series))].sort((a,b)=>a.localeCompare(b,'fr')).map(x=>[x,x]));return `<fieldset data-kan-challenge><legend>Défi ${i+1}</legend><div class="kan-admin-grid"><label>Identifiant stable<input name="cid" value="${esc(c.id)}" pattern="[a-z0-9][a-z0-9-]{1,39}" maxlength="40" required></label><label>Nom<input name="label" value="${esc(c.label)}" minlength="3" maxlength="100" required></label><label class="wide">Description<textarea name="description" maxlength="400">${esc(c.description)}</textarea></label><label>Difficulté<select name="difficulty">${options({discovery:'Découverte',collector:'Collection',prestige:'Prestige · facultatif'},c.difficulty)}</select></label><label>Action mesurée<select name="metric">${options(metrics,c.metric)}</select></label><label>Objectif<input name="goal" type="number" min="1" max="999999" step="1" value="${c.goal}" required></label><label>Anime · pour le défi d’un univers<select name="universe"><option value="">Choisir un anime</option>${options(universes,c.universe)}</select></label><label>Éveil minimum · pour le défi d’Éveil<select name="min_level">${options({1:'Éveil I',2:'Éveil II',3:'Éveil III'},c.min_level)}</select></label><label>Récompense<select name="reward_kind">${options(kinds,c.reward.kind)}</select></label><label>Nom de la récompense<input name="reward_label" value="${esc(c.reward.label)}" minlength="2" maxlength="90" required></label><label>Style de la récompense<select name="reward_style">${options(themes,c.reward.style)}</select></label></div><details><summary>Limiter à des personnages précis · ${c.card_ids.length} sélectionné(s)</summary><p>Sans sélection, tous les personnages conviennent. Cette sélection s’applique aux tirages, Résonances et Éveils, pas au nombre de boosters.</p><label>Personnages · Ctrl ou Cmd pour sélectionner plusieurs cartes<select name="card_ids" multiple size="7">${cards.map(x=>`<option value="${esc(x.id)}" ${c.card_ids.includes(x.id)?'selected':''}>${esc(x.name+' · '+x.series+' · '+x.rarity+' ['+x.id+']')}</option>`).join('')}</select></label></details><button type="button" class="ks-text-button" data-kan-remove="${i}" data-kan-write>Retirer ce défi</button></fieldset>`;}
 function form(config=editing?.config||fresh()){const f=$('kanEventForm');if(!f)return;f.innerHTML=`<h3>${esc(editing?.config.title||'Nouvelle Anomalie')}</h3><p>${editing?.live?'Les modifications restent en brouillon jusqu’à leur publication. Après le début, les dates et les défis publiés sont figés.':'Ce brouillon sera visible uniquement par les administrateurs.'}</p><div class="kan-admin-grid"><label>Nom<input name="title" value="${esc(config.title)}" minlength="3" maxlength="90" required></label><label>Identité graphique<select name="theme">${options(themes,config.theme)}</select></label><label class="wide">Présentation<textarea name="description" maxlength="1200" rows="3">${esc(config.description)}</textarea></label><label>Début · UTC<input name="starts_at" type="datetime-local" value="${stamp(config.starts_at)}"></label><label>Fin · UTC<input name="ends_at" type="datetime-local" value="${stamp(config.ends_at)}"></label><label>Illustration facultative · URL HTTPS<input name="image" type="url" value="${esc(config.image)}" placeholder="https://…/illustration.webp"></label><label>Source de l’illustration<input name="image_source" type="url" value="${esc(config.image_source)}" placeholder="https://…"></label></div><p class="ka-note">Sans illustration, le décor Kizuna du thème est utilisé. Indique la source d’une image que tu es autorisé à utiliser. Les dates sont saisies en UTC.</p><div id="kanChallengeForms">${config.challenges.map(challengeForm).join('')}</div><div class="ka-actions"><button class="ks-button ks-secondary" type="button" data-kan-admin="add" data-kan-write>Ajouter un défi</button><button class="ks-button ks-secondary" type="button" data-kan-admin="preview" data-kan-write>Prévisualiser</button><button class="ks-button" type="submit" data-kan-write>Enregistrer le brouillon</button></div><div class="ka-actions"><button id="kanPublish" class="ks-button" type="button" data-kan-admin="publish">Publier / programmer</button><button id="kanToggle" class="ks-button ks-secondary" type="button" data-kan-admin="toggle">${editing?.live?.enabled?'Désactiver':'Activer'}</button><button id="kanParticipants" class="ks-button ks-secondary" type="button" data-kan-admin="participants">Voir les participations</button><button id="kanArchive" class="ks-button ks-secondary" type="button" data-kan-admin="archive">Archiver après la fin</button></div><p class="ka-note">La publication rend l’Anomalie visible. Si le début est futur, les défis démarrent à l’heure programmée. Enregistre tes modifications avant de publier.</p>`;controls();}
 function read(){const f=$('kanEventForm'),v=n=>f.elements.namedItem(n)?.value||'',iso=n=>v(n)?new Date(v(n)+'Z').toISOString():null;return {title:v('title'),description:f.querySelector(':scope > .kan-admin-grid [name="description"]').value,theme:v('theme'),image:v('image'),image_source:v('image_source'),starts_at:iso('starts_at'),ends_at:iso('ends_at'),challenges:[...f.querySelectorAll('[data-kan-challenge]')].map(row=>{const x=n=>row.querySelector('[name="'+n+'"]').value;return {id:x('cid'),label:x('label'),description:x('description'),difficulty:x('difficulty'),metric:x('metric'),goal:Number(x('goal')),universe:x('universe'),min_level:Number(x('min_level')),card_ids:[...row.querySelector('[name="card_ids"]').selectedOptions].map(n=>n.value),reward:{kind:x('reward_kind'),label:x('reward_label'),style:x('reward_style')}};})};}
 function accept(r){drafts=r.drafts;editing=drafts.find(d=>d.id===(r.saved_id||editing?.id))||editing;dirty=false;list();form();$('kanAdminPreview').hidden=true;window.KizunaAnomalies?.refresh(true);}
 async function participants(next=0){if(!editing)return;const r=await run('participants',{id:editing.id,page:next});if(!r)return;page=next;const panel=$('kanParticipantsPanel');panel.hidden=false;panel.innerHTML=`<h3>Participations réelles · ${esc(editing.config.title)}</h3><div class="kan-admin-participants">${r.participants.slice(0,25).map(p=>`<article><strong>${esc(p.username)}</strong><span>Première participation : ${esc(new Date(p.first_at).toLocaleString('fr-FR'))}</span><span>${p.rewards} récompense(s) réclamée(s)</span></article>`).join('')||'<p>Aucune participation enregistrée pour le moment.</p>'}</div><div class="ka-actions"><button type="button" class="ks-button ks-secondary" data-kan-page="${page-1}" ${page===0?'disabled':''}>Précédente</button><span>Page ${page+1}</span><button type="button" class="ks-button ks-secondary" data-kan-page="${page+1}" ${r.participants.length<26?'disabled':''}>Suivante</button></div>`;status('Participations chargées.');}
 async function submit(e){e.preventDefault();if(busy||!allowed())return;if(e.target.id==='kanThresholdForm'){const thresholds=[0,1,2].map(i=>Number(e.target.elements['level'+i].value));if(!thresholds.every((n,i)=>Number.isInteger(n)&&n>=1&&n<=100000&&(!i||n>thresholds[i-1]))){status('Les trois seuils doivent être des entiers strictement croissants.');return;}if(!confirm('Appliquer les seuils '+thresholds.join(' / ')+' ? Les Éveils déjà obtenus seront conservés.'))return;const token=epoch;busy=true;controls();try{const r=await window.KizunaAccount.mythicRequest('settings',{thresholds,revision:rules.revision});if(token!==epoch||!allowed())return;rules=r.rules;renderThresholds();window.KizunaMythic?.refresh(true);status('Seuils enregistrés.');}catch(err){if(token===epoch)status(err.publicMessage||err.message);}finally{if(token===epoch){busy=false;controls();}}return;}
  if(e.target.id==='kanEventForm'){let config;try{config=read();}catch{status('Vérifie les dates saisies.');return;}const r=await run('save',{id:editing?.id||null,revision:editing?.revision,config});if(r){accept(r);status('Brouillon enregistré. Il reste à le publier.');}}
 }
 async function click(e){const b=e.target.closest('button');if(!b||b.disabled||busy||!allowed())return;if(b.dataset.kanEdit){if(dirty&&!confirm('Abandonner les modifications non enregistrées ?'))return;editing=drafts.find(d=>d.id===b.dataset.kanEdit);dirty=false;form();$('kanParticipantsPanel').hidden=true;return;}if(b.hasAttribute('data-kan-remove')){const c=read();if(c.challenges.length===1){status('Conserve au moins un défi.');return;}c.challenges.splice(Number(b.dataset.kanRemove),1);dirty=true;form(c);return;}if(b.hasAttribute('data-kan-page'))return participants(Number(b.dataset.kanPage));const action=b.dataset.kanAdmin;if(!action)return;
  if(action==='new'){if(dirty&&!confirm('Abandonner les modifications non enregistrées ?'))return;editing=null;dirty=false;form();$('kanAdminPreview').hidden=true;$('kanParticipantsPanel').hidden=true;status('Nouvelle Anomalie privée.');}
  else if(action==='refresh'){if(dirty&&!confirm('Actualiser la liste en conservant ton formulaire ?'))return;load();}
  else if(action==='add'){const c=read();if(c.challenges.length>=12){status('Douze défis maximum.');return;}let i=c.challenges.length+1;while(c.challenges.some(x=>x.id==='defi-'+i))i++;c.challenges.push(challenge(i));dirty=true;form(c);}
  else if(action==='preview'){const f=$('kanEventForm');if(!f.reportValidity())return;const preview=$('kanAdminPreview');preview.hidden=false;preview.innerHTML='<h3>Aperçu privé · aucune participation simulée</h3>'+window.KizunaAnomalies.preview(read());}
  else if(action==='participants')participants();
  else if(editing&&['publish','toggle','archive'].includes(action)){if(action==='publish'&&dirty)return;const verb={publish:'Publier cette Anomalie avec ses dates et récompenses ?',toggle:editing.live?.enabled?'Désactiver cette Anomalie ? Les récompenses obtenues restent acquises.':'Réactiver cette Anomalie ?',archive:'Archiver cet événement terminé ? Les récompenses restent acquises.'}[action];if(!confirm(verb))return;const r=await run(action,{id:editing.id,revision:editing.revision,enabled:!editing.live?.enabled});if(r){accept(r);status({publish:'Anomalie publiée. Son démarrage suit les dates programmées.',toggle:'Visibilité mise à jour.',archive:'Anomalie archivée.'}[action]);}}
 }
 function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;mount();});}new MutationObserver(schedule).observe(document.querySelector('main'),{childList:true,subtree:true});document.addEventListener('kizuna:account-change',schedule);schedule();
})();
